-- 거래처 **만료일 이관 누락 복구** (발주처 지적 2026-11-12)
--
-- 레거시 거래처관리는 거래를 끝낼 때 `custData.endDate` 에 날짜를 적었고, 목록을
-- `where len(endDate) = 0` 으로 걸러 만료 거래처를 숨겼다(`거래처관리.vb:96`).
-- 우리 화면·쿼리는 그 로직 그대로인데(`PartnerRepository.search` 의 `includeExpired`)
-- **값이 이관되지 않아** 만료 거래처가 거래처 선택·주문 트리에 그대로 나왔다.
--
-- 레거시 실측(.bak): DSLab 370곳 + DSTxtBook 88곳 = **458곳**.
--   형식 `yyyyMMdd_HHmmss` 15자 고정 · 두 장부 중복 0 · 이상값 0 · 2016~2026년.
--   날짜만 쓴다(`partners.end_date` 가 DATE).
--
-- ‼️**이미 값이 있는 행은 건드리지 않는다**(`end_date IS NULL` 조건).
--   운영에 만료일이 든 17곳은 전부 이 프로그램에서 [거래 종료]한 시험 거래처(ZZT…)이고,
--   레거시 값으로 덮으면 그 기록이 사라진다.
--
-- ‼️DSRE 쪽 만료(`tbl_cust_info.END_GUBUN='Y'`)는 **이 작업 범위가 아니다**.
--   레거시 매출프로그램은 END_GUBUN 을 한 번도 읽지 않았고(소스 전체 0건), 두 시스템이
--   각자 관리해 어긋나 있다 — 레거시 370곳 ∩ DSRE 51곳 = 32곳뿐이고
--   **DSRE 에서만 만료인 19곳**은 이 이관으로 안 잡힌다. 그건 동기화에 따로 붙인다.

CREATE TEMPORARY TABLE _legacy_end (
    code     VARCHAR(20) NOT NULL PRIMARY KEY,
    end_date DATE        NOT NULL
);


UPDATE partners p
  JOIN _legacy_end e ON e.code = p.code
   SET p.end_date = e.end_date
 WHERE p.end_date IS NULL;

DROP TEMPORARY TABLE _legacy_end;
